javas.java:

double def seniorityAllowance(double:baseSalary, int:years) {
    if (years >= 20) {
        return baseSalary * 0.08;
    } else if (years >= 10) {
        return baseSalary * 0.05;
    } else if (years >= 5) {
        return baseSalary * 0.03;
    } else if (years >= 1) {
        return baseSalary * 0.01;
    } else {
        return 0.0;
    }
}


int def highTempAllowance(int:days, boolean:outdoor) {
    if (outdoor) {
        return days * 30;
    } else {
        return days * 15;
    }
}


double def overtimePay(double:hourlyBase, double:hours, str:type) {
    if (type == "HOLIDAY") {
        return hourlyBase * hours * 3.0;
    } else if (type == "WEEKEND") {
        return hourlyBase * hours * 2.0;
    } else {
        return hourlyBase * hours * 1.5;
    }
}


double def remoteAreaAllowance(double:baseSalary, boolean:remote) {
    if (remote) {
        return baseSalary * 0.10;
    } else {
        return 0.0;
    }
}


int def perfectAttendanceBonus(boolean:perfect) {
    if (perfect) {
        return 300;
    } else {
        return 0;
    }
}


double def performanceBonus(double:baseSalary, int:score) {
    if (score >= 95) {
        return baseSalary * 0.30;
    } else if (score >= 85) {
        return baseSalary * 0.20;
    } else if (score >= 70) {
        return baseSalary * 0.10;
    } else if (score >= 60) {
        return baseSalary * 0.05;
    } else {
        return 0.0;
    }
}
